-- ============================================================================
-- Seed: 040_nj_municipality (565 rows)
--
-- The UNION of every NJ municipality observed in the 2016-2024 NJ DCA
-- workbooks (565 unique (muni_code, county_fips) pairs).
-- The 2024 workbook alone publishes 564 munis (post-Princeton-merger);
-- earlier years reference a small number of additional muni codes that
-- have since been retired through municipal consolidation. We seed the
-- UNION so the FK from raw.nj_property_tax_muni to ref.nj_municipality
-- holds across the full historical ingest.
--
-- Keying: 4-digit MuniCode. First 2 digits = DCA county code 01..21,
-- last 2 digits = municipal index within the county; '00' suffix
-- denotes the county-level summary and is excluded by CHECK constraint.
--
-- Source family: NJ Division of Local Government Services, annual
-- '{YY}taxes.xls' workbooks (2016-2024).
--   https://www.nj.gov/dca/dlgs/resources/Property_Tax_info.shtml
--   Sheet: 'Municipal Tax Summary'. When a muni_code appears in
--   multiple vintages with a different muni_name spelling, the
--   most recent observation wins (NJ DCA occasionally re-spells
--    'Borough' / 'Boro', etc.).
--
-- Generated by: scripts/_generate_phase8_muni_seed.py (one-shot).
-- Idempotent under re-run via the muni_code conflict handler.
-- ============================================================================

ON CONFLICT (muni_code) DO UPDATE SET
    muni_name       = EXCLUDED.muni_name,
    county_fips     = EXCLUDED.county_fips,
    source_url      = EXCLUDED.source_url,
    source_citation = EXCLUDED.source_citation;
